<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {useCasesStore} from '../features/cases/store';
import {useRoute} from 'vue-router';
import AppHeader from '../components/AppHeader.vue';
import GuideLink from '../components/GuideLink.vue';
import {useAccountStore} from '../stores/account';
import schema from '../../../shared/profile.schema.json';
import {profilePayload} from '../services/profileFacts';
import {api} from '../core/http';
import {emptyWorkspace,loadWorkspace,saveWorkspace,formAssertions,parseSupplement,resolvedFacts,indexedWorkspace,exportWorkspace,importWorkspace,type Assertion} from '../services/clientWorkspace';
const account=useAccountStore(),owner=computed(()=>account.user?.id||'offline');
const data=ref(emptyWorkspace(owner.value)),error=ref(''),message=ref(''),busy=ref(false),scope=ref(''),until=ref('');
const cases=useCasesStore(),route=useRoute();scope.value=String(route.query.case||'');const choices=computed(()=>[...new Map([...cases.items,...(cases.selected?[cases.selected]:[])].map(item=>[item.id,item])).values()]);
const properties=schema.properties as Record<string,any>;
const labels:Record<string,string>={school:'学校',student_type:'身份',college:'学院',major:'专业',class_name:'班级',enrollment_year:'入学年份',graduation_year:'毕业年份',role:'角色',rank_percent:'排名百分比',team_size:'学生队员人数',certificate_level:'证书等级',moral_score:'德育成绩',advisor_count:'指导教师人数',participation_count:'当前赛事参赛次数',disciplinary_status:'处分记录',coursework_status:'课程合格情况',fitness_status:'体育合格情况',moral_bonus_items:'德育加分项目'};
const categories:Record<string,string>={academic:'教务',award:'奖助评优',exam:'考试',competition:'竞赛',research:'科研申报',career:'就业实习',other:'其他'};
async function saveInterests(){await persist();message.value='关注分类已保存在本机，不覆盖硬性资格判断。'}
const enums:Record<string,string>={undergraduate:'本科生',graduate:'研究生',teacher:'教师',other:'其他',clear:'无记录',recorded:'有记录',passed:'合格',failed:'不合格'};
const conflicts=computed(()=>resolvedFacts(data.value,scope.value).conflicts);
let loadVersion=0;async function reload(){const version=++loadVersion,identity=owner.value;data.value=emptyWorkspace(identity);try{const loaded=await loadWorkspace(identity);if(version===loadVersion&&identity===owner.value)data.value=loaded}catch(e:any){if(version===loadVersion)error.value=e.message}}
onMounted(reload);watch(owner,reload);
async function persist(){data.value=await saveWorkspace(data.value)}
async function saveForm(){busy.value=true;error.value='';try{const facts=profilePayload(data.value.form).facts;const fresh=formAssertions(facts,scope.value,until.value||null);data.value.history=[...data.value.history,{at:new Date().toISOString(),assertions:data.value.assertions.filter(a=>a.source==='form'&&a.scope===scope.value)}].slice(-500);data.value.assertions=[...data.value.assertions.filter(a=>a.source!=='form'||a.scope!==scope.value),...fresh];data.value.form=facts;await persist();message.value='个人画像已保存在本机，匹配将读取这份资料。'}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function parse(){error.value='';try{const rows=parseSupplement(data.value.supplement,scope.value);data.value.assertions=[...data.value.assertions.filter(a=>a.source!=='supplement'||a.confirmed),...rows];await persist();message.value=rows.length?'补充内容已生成候选，请逐项确认。':'补充原文已保存在本机；未提取到可安全计算的字段，保留待核对。'}catch(e:any){error.value=e.message}}
async function confirm(a:Assertion){error.value='';try{a.validUntil=a.validUntil||null;a.confirmed=true;await persist();message.value='资料卡已确认；冲突资料仍按未知处理。'}catch(e:any){a.confirmed=false;error.value=e.message}}
function edit(a:Assertion,value:string){const spec=properties[a.field];a.value=spec.type.includes('number')||spec.type.includes('integer')?Number(value):spec.type.includes('array')?value.split(/[、,，]/).filter(Boolean):value;a.source='form';a.quote=`用户修改 ${labels[a.field]||a.field} = ${JSON.stringify(a.value)}`;a.confirmed=false}
async function remove(id:string){data.value.assertions=data.value.assertions.filter(a=>a.id!==id);await persist()}
async function migrate(){try{const facts=await api('/api/v1/profile');data.value.form=facts;data.value.assertions.push(...formAssertions(profilePayload(facts).facts).map(a=>({...a,confirmed:false})));await persist();message.value='原账户资料已复制到本机，请核对；后续不自动上传画像。'}catch(e:any){error.value=e.message}}
function backup(){const blob=new Blob([exportWorkspace(data.value)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='zhishi-private-backup.json';link.click();URL.revokeObjectURL(url)}
async function restore(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{data.value=await importWorkspace(await file.text(),owner.value);message.value='本机资料已恢复。'}catch(e:any){error.value=e.message}}
async function erase(){if(!window.confirm('删除当前身份在本机的画像、补充说明和课表？此操作不会删除服务器事项。'))return;await indexedWorkspace.remove(owner.value);data.value=emptyWorkspace(owner.value);message.value='本机资料已删除。';window.dispatchEvent(new CustomEvent('zhishi-client-changed',{detail:{owner:owner.value}}))}
</script>
<template><div class="page page--utility"><AppHeader title="个人画像"/><GuideLink topic="profile" label="资料确认、适用范围与冲突处理说明"/><p class="notice">资料默认保存在当前设备，可离线查看修改；不会自动上传补充说明。{{account.signedIn?'当前账户资料独立保存。':'当前为本机体验资料，与登录账户隔离。'}}</p><p v-if="error" class="notice notice--danger" role="alert">{{error}}</p><p v-if="message" class="notice notice--success" role="status">{{message}}</p>
<form class="surface-card form-card" @submit.prevent="saveForm"><h2>通用资料</h2><label v-for="(spec,key) in properties" :key="key">{{labels[String(key)]||key}}<select v-if="spec.enum" v-model="data.form[key]" :aria-label="labels[String(key)]||String(key)"><option :value="null">待补充</option><option v-for="value in spec.enum.filter((v:any)=>v!==null)" :key="value" :value="value">{{enums[value]||value}}</option></select><input v-else-if="spec.type.includes('number')||spec.type.includes('integer')" v-model.number="data.form[key]" type="number" :min="spec.minimum" :max="spec.maximum" :step="spec.type.includes('integer')?1:'any'"><input v-else v-model="data.form[key]" :maxlength="spec.maxLength||3000"></label><label>资料适用范围<select v-model="scope" aria-label="资料适用范围"><option value="">通用资料</option><option v-for="item in choices" :key="item.id" :value="item.id">{{item.title}}</option><option v-if="scope&&!choices.some(item=>item.id===scope)" :value="scope">当前指定事项</option></select></label><label>资料有效至（选填）<input v-model="until" type="date"></label><button class="button button--primary" :disabled="busy">保存画像</button></form>
<section class="surface-card form-card"><h2>补充说明</h2><label>其他个人情况<textarea v-model="data.supplement" maxlength="10000" rows="5" placeholder="例如：我是本科生，德育成绩85。不能确认的内容会保留待核对。"></textarea></label><button class="button button--secondary" @click="parse">在本机整理补充内容</button><p>不会直接执行补充文字；只有确认、未过期且无冲突的资料参与判断。</p></section>
<section class="surface-card"><h2>本机资料卡</h2><p v-if="conflicts.length" class="notice notice--warning">存在冲突：{{conflicts.map(k=>labels[k]||k).join('、')}}，相关字段暂按未知处理。</p><article v-for="a in data.assertions" :key="a.id" class="fact-card"><h3>{{labels[a.field]||a.field}} · {{a.confirmed?'已确认':'待确认'}}</h3><label>资料值<select v-if="properties[a.field]?.enum" :value="a.value" @change="edit(a,($event.target as HTMLSelectElement).value)"><option v-for="value in properties[a.field].enum.filter((v:any)=>v!==null)" :key="value" :value="value">{{enums[value]||value}}</option></select><input v-else :value="Array.isArray(a.value)?a.value.join('、'):a.value" @input="edit(a,($event.target as HTMLInputElement).value)"></label><blockquote>{{a.quote}}</blockquote><label>资料卡有效至<input v-model="a.validUntil" type="date" @change="a.confirmed=false"></label><label>资料卡适用事项<input v-model="a.scope" @input="a.confirmed=false"></label><small>来源：{{a.source==='form'?'用户表单':'用户补充'}} · {{a.scope?(choices.find(item=>item.id===a.scope)?.title||'指定事项，需核对'):'通用'}} · {{a.validUntil||'未声明有效期'}}</small><div class="button-row"><button class="button button--secondary" @click="confirm(a)">确认资料</button><button class="button button--secondary" @click="remove(a.id)">删除资料卡</button></div></article><p v-if="!data.assertions.length">尚无已确认资料。</p></section>
<section class="surface-card"><h2>关注分类</h2><label v-for="(label,key) in categories" :key="key"><input v-model="data.interests" type="checkbox" :value="key">{{label}}</label><button class="button button--secondary" @click="saveInterests">保存关注分类</button></section><section class="surface-card"><h2>备份与清理</h2><p>备份含个人资料和课表，请自行保管；退出登录会清理该账户的本机资料。</p><button class="button button--secondary" @click="backup">导出本机备份</button><label>恢复本账户备份<input type="file" accept="application/json" @change="restore"></label><button v-if="account.signedIn" class="button button--secondary" @click="migrate">复制原账户画像到本机</button><button class="button button--secondary" @click="erase">删除本机资料</button><details><summary>资料历史（最近500次）</summary><details v-for="(row,index) in data.history" :key="index"><summary>{{row.at}} · {{row.assertions?.length||0}} 条旧资料</summary><p v-for="a in row.assertions||[]" :key="a.id">{{labels[a.field]||a.field}}：{{a.value}} · {{a.quote}}</p></details></details></section><RouterLink class="button button--secondary" to="/timetable">管理课表</RouterLink></div></template>
<style scoped>.fact-card{border-bottom:1px solid #ddd;padding:12px 0}.fact-card label{display:block;margin:8px 0}.fact-card input,.fact-card select{max-width:100%;width:100%}blockquote{margin:8px 0;overflow-wrap:anywhere}textarea{width:100%;box-sizing:border-box}small{overflow-wrap:anywhere}</style>
